// Function to check if an IP address matches a CIDR range  
int ip_in_cidr(char *ip_str, char *cidr_str) {  
    struct in_addr ip_addr;  
    struct in_addr cidr_addr;  
    unsigned int ip_int, cidr_int;  
    int cidr_bits;  
    char *token;  

    // Parse IP address  
    if (inet_aton(ip_str, &ip_addr) == 0) {  
        return 0; // Invalid IP address  
    }  
    ip_int = ntohl(ip_addr.s_addr);  

    // Parse CIDR range  
    token = strtok(cidr_str, "/");  
    if (token == NULL) {  
        return 0; // Invalid CIDR format  
    }  
    cidr_addr.s_addr = inet_addr(token);  
    if (cidr_addr.s_addr == INADDR_NONE) {  
        return 0; // Invalid CIDR IP address  
    }  
    cidr_int = ntohl(cidr_addr.s_addr);  

    token = strtok(NULL, "/");  
    if (token == NULL) {  
        return 0; // Invalid CIDR format  
    }  
    cidr_bits = atoi(token);  

    // Check if IP address matches CIDR range  
    unsigned int mask = 0xFFFFFFFFUL << (32 - cidr_bits);  
    return ((ip_int & mask) == (cidr_int & mask));  
}  

