int ip_in_whitelist(char *ip_str, char *whitelist_str) {  
    char *token;  
    char *ip_token;  

    // Parse whitelist string  
    token = strtok(whitelist_str, ",");  
    while (token != NULL) {  
        ip_token = strtok(token, " ");  
        if (ip_token != NULL && strcmp(ip_token, ip_str) == 0) {  
            return 1; // IP address is whitelisted  
        }  
        token = strtok(NULL, ",");  
    }  
    return 0; // IP address is not whitelisted  
}

