    // Check if the directory is writable by others  
    if ((sb.st_mode & S_IWOTH) != 0) {  
        // Remove write permission for others  
        chmod(directory_path, sb.st_mode & ~S_IWOTH);  
    }  

    // Check if the directory is executable by others  
    if ((sb.st_mode & S_IXOTH) != 0) {  
        // Remove execute permission for others  
        chmod(directory_path, sb.st_mode & ~S_IXOTH);  
    }  

    // Check if the directory is readable by others  
    if ((sb.st_mode & S_IXOTH) != 0) {  
        // Remove read permission for others  
        chmod(directory_path, sb.st_mode & ~S_IXOTH);  
    }  

    // Set ownership to current user only  
    uid_t uid = getuid();  
    gid_t gid = getgid();  
    if (chown(directory_path, uid, gid) != 0) {  
        perror("Error changing ownership");  
        return -1;  
    }  

    printf("Directory access blocked successfully for non-owners.\n");  
    return 0;  
}  

