// Function to check if an IP address is within a CIDR range  
int is_ip_in_cidr(const char* ip_str, const char* cidr_str) {  
    struct in_addr ip_addr;  
    struct in_addr cidr_addr;  
    uint32_t ip_int, cidr_int;  
    int cidr_prefix_len;  
    int i;  

    // Convert IP address string to integer  
    if (inet_aton(ip_str, &ip_addr) == 0) {  
        return 0; // Invalid IP address  
    }  
    ip_int = ntohl(ip_addr.s_addr);  

    // Parse CIDR notation  
    char* cidr_end;  
    cidr_prefix_len = strtol(cidr_str + strlen(cidr_str) - 1, &cidr_end, 10);  
    if (cidr_end == cidr_str || cidr_prefix_len < 0 || cidr_prefix_len > 32) {  
        return 0; // Invalid CIDR notation  
    }  

    // Convert CIDR address string to integer  
    if (inet_aton(cidr_str, &cidr_addr) == 0) {  
        return 0; // Invalid CIDR address  
    }  
    cidr_int = ntohl(cidr_addr.s_addr);  

    // Calculate subnet mask  
    uint32_t subnet_mask = 0xFFFFFFFFUL << (32 - cidr_prefix_len);  

    // Check if IP address is within CIDR range  
    return (ip_int & subnet_mask) == (cidr_int & subnet_mask);  
}  

