// Function to check if a user is allowed to access the directory  
int is_user_allowed(const char* username, const char* directory_path) {  
    struct passwd *pwd;  
    struct group *grp;  
    struct stat file_stat;  

    // Check if the directory exists  
    if (stat(directory_path, &file_stat) != 0) {  
        return 0; // Directory does not exist  
    }  

    // Get user information  
    pwd = getpwnam(username);  
    if (!pwd) {  
        return 0; // User not found  
    }  

    // Check if the user has read permissions on the directory  
    if ((file_stat.st_mode & S_IRUSR) == 0) {  
        return 0; // User does not have read permission  
    }  

    // Check if the user is in the group that owns the directory  
    grp = getgrnam(pwd->pw_name);  
    if (!grp) {  
        return 0; // Group not found  
    }  

    // Check if the user has write permissions on the directory  
    if ((file_stat.st_mode & S_IWUSR) == 0) {  
        return 0; // User does not have write permission  
    }  

    // Check if the user is in the group that owns the directory  
    for (int i = 0; i < grp->gr_memcnt; i++) {  
