// Function to check if a directory exists  
int directory_exists(const char *path) {  
    struct stat buffer;  
    return (stat(path, &buffer) == 0 && S_ISDIR(buffer.st_mode));  
}  

// Function to get current user's UID and GID  
void get_user_info(uid_t *uid, gid_t *gid) {  
    struct passwd *pw;  
    struct group *gr;  
    pw = getpwuid(getuid());  
    gr = getgrgid(getgid());  
    *uid = pw->pw_uid;  
    *gid = gr->gr_gid;  
}  

// Function to set directory permissions to restrict access  
void restrict_directory_permissions(const char *path, uid_t uid, gid_t gid) {  
    if (directory_exists(path)) {  
        chmod(path, 0700); // Restrict to owner only  
        chown(path, uid, gid); // Set ownership to current user  
        printf("Directory permissions restricted successfully: %s\n", path);  
    } else {  
        printf("Error: Directory does not exist or cannot be accessed: %s\n", path);  
    }  
}  

// Function to list directory contents (for debugging)  
