// Function to count unique IP addresses in a list  
int countUniqueIPs(char **ips, int count) {  
    if (count == 0) return 0;  

    int uniqueCount = 0;  
    char **seen = malloc(count * sizeof(char*));  
    memset(seen, 0, count * sizeof(char*));  

    for (int i = 0; i < count; i++) {  
        int found = 0;  
        for (int j = 0; j < uniqueCount; j++) {  
            if (strcmp(ips[i], seen[j]) == 0) {  
                found = 1;  
                break;  
            }  
        }  
        if (!found) {  
            seen[uniqueCount] = strdup(ips[i]);  
            uniqueCount++;  
        }  
    }  

    free(seen);  
    return uniqueCount;  
}  

