// Function to check if a directory exists  
int directory_exists(const char *path) {  
    struct stat buffer;  
    return (stat(path, &buffer) == 0 && S_ISDIR(buffer.st_mode));  
}  

// Function to block access to a directory by setting permissions  
int block_directory_access(const char *path) {  
    if (!directory_exists(path)) {  
        fprintf(stderr, "Error: Directory does not exist at %s\n", path);  
        return -1;  
