    // Set read-only permissions for the directory  
    chmod(path, 0444);  

    // Set ownership to root to prevent unauthorized access  
    chown(path, 0, 0);  

    printf("Access to directory %s has been blocked successfully.\n", path);  
    return 0;  
}  

