// Function to parse CIDR notation and return the IP address and prefix length
pair<string, int> parseCIDR(const string& cidr) {
    regex cidrPattern(R"((\d{1,3}\.){3}\d{1,3}(/(\d{1,2}))?)");
    smatch match;
    if (regex_match(cidr, match, cidrPattern)) {
        string ip = match[1].str();
        int prefix = match[3].matched ? stoi(match[3].str()) : 0;
        return make_pair(ip, prefix);
    }
    return make_pair("", 0);
}

