class IPBlocker {
private:
    std::unordered_set<std::string> trustedIPs;
    std::mutex mtx;
    bool emergencyMode = false;
    std::thread blockingThread;
    volatile bool running = true;

public:
    IPBlocker() {
        // Initialize with default trusted IPs
        trustedIPs.insert("<ip-address>");
        trustedIPs.insert("<ip-address>");
        trustedIPs.insert("<ip-address>");
    }

    void addTrustedIP(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mtx);
        trustedIPs.insert(ip);
    }

    void removeTrustedIP(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mtx);
        trustedIPs.erase(ip);
    }

    void setEmergencyMode(bool mode) {
        std::lock_guard<std::mutex> lock(mtx);
        emergencyMode = mode;
    }

    void startBlocking() {
        if (blockingThread.joinable()) {
            blockingThread.join();
        }
        blockingThread = std::thread(&IPBlocker::blockingLoop, this);
    }

    void stopBlocking() {
        running = false;
        if (blockingThread.joinable()) {
            blockingThread.join();
        }
    }

    void blockingLoop() {
        while (running) {
            // Simulate blocking traffic from untrusted sources
            std::this_thread::sleep_for(std::chrono::seconds(1));

            // Check if emergency mode is active
            if (emergencyMode) {
                std::cout << "Emergency mode active: Traffic from untrusted sources is allowed.\n";
                continue;
            }

            // Block traffic from untrusted sources
            std::cout << "Blocking traffic from untrusted sources...\n";
        }
    }

    void handleSignal(int sig) {
        std::cout << "Received signal " << sig << ". Stopping blocking...\n";
        stopBlocking();
    }
};

