vector<string> parseCIDR(const string& cidr) {
    vector<string> result;
    regex cidr_regex(R"((\d{1,3}\.){3}\d{1,3}(/(\d+))?)");
    smatch match;
    string ip_range = cidr;
    if (regex_search(ip_range, match, cidr_regex)) {
        string ip = match[1].str();
        int prefix = stoi(match[3].str());
        // Convert IP to long integer
        long ip_int = inet_addr(ip.c_str());
        // Calculate the range based on prefix
        long mask = 0xFFFFFFFFUL << (32 - prefix);
        long start = ip_int & ~mask;
        long end = (ip_int | mask) - 1;
        // Convert back to string
        char buffer[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &start, buffer, INET_ADDRSTRLEN);
        result.push_back(buffer);
        inet_ntop(AF_INET, &end, buffer, INET_ADDRSTRLEN);
        result.push_back(buffer);
    }
    return result;
}

// Function to check if an IP address is in a CIDR range
bool isIPInRange(const string& ip, const vector<string>& range) {
    long ip_int = inet_addr(ip.c_str());
    long start = inet_addr(range[0].c_str());
    long end = inet_addr(range[1].c_str());
    return (ip_int >= start && ip_int <= end);
}

