class IPBlocker {
public:
    static std::vector<std::string> blockIPs(const std::vector<std::string>& ipRanges) {
        std::vector<std::string> blockedIPs;
        for (const auto& range : ipRanges) {
            std::istringstream iss(range);
            std::string ipStr, cidr;
            std::getline(iss, ipStr, '/');
            std::getline(iss, cidr);
            if (cidr.empty()) continue;
            std::bitset<32> ip = parseIP(ipStr);
            std::bitset<32> mask = parseCIDR(cidr);
            std::bitset<32> blocked = ip & mask;
            std::ostringstream oss;
            oss << std::hex << std::setfill('0') << std::setw(8) << blocked.to_ulong();
            blockedIPs.push_back(oss.str());
        }
        return blockedIPs;
    }

private:
    static std::bitset<32> parseIP(const std::string& ip) {
        std::bitset<32> result;
        std::istringstream iss(ip);
        std::string octet;
        int count = 0;
        while (std::getline(iss, octet, '.')) {
            if (count >= 4) break;
            int val = std::stoi(octet);
            if (val < 0 || val > 255) return result;
            result <<= 8;
            result |= std::bitset<8>(val);
            count++;
        }
        return result;
    }

    static std::bitset<32> parseCIDR(const std::string& cidr) {
        std::bitset<32> mask;
        int prefix = std::stoi(cidr);
        for (int i = 0; i < prefix; ++i) {
            mask <<= 1;
            mask |= 1;
        }
        return mask;
    }
};

