// Function to check if a directory exists  
int directory_exists(const char* path) {  
    struct stat buffer;  
    return (stat(path, &buffer) == 0 && S_ISDIR(buffer.st_mode));  
}  

// Function to set directory permissions to read-only  
int set_directory_permissions(const char* path) {  
    if (!directory_exists(path)) {  
        fprintf(stderr, "Error: Directory does not exist: %s\n", path);  
        return -1;  
    }  

    // Set permissions to read-only (0444)  
    if (chmod(path, 0444) == -1) {  
        fprintf(stderr, "Error: Failed to set directory permissions: %s\n", strerror(errno));  
        return -1;  
    }  

    printf("Directory permissions set to read-only: %s\n", path);  
    return 0;  
}  

// Function to block access by removing execute permissions  
int block_directory_access(const char* path) {  
    if (!directory_exists(path)) {  
        fprintf(stderr, "Error: Directory does not exist: %s\n", path);  
        return -1;  
    }  

    // Remove execute permissions (0444)  
    if (chmod(path, 0444) == -1) {  
        fprintf(stderr, "Error: Failed to block directory access: %s\n", strerror(errno));  
        return -1;  
    }  

    printf("Directory access blocked: %s\n", path);  
    return 0;  
}  

// Main function to demonstrate usage  
int main(int argc, char* argv[]) {  
    if (argc != 2) {  
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);  
        return 1;  
    }  

    const char* directory_path = argv[1];  

    // Block access to the specified directory  
    if (block_directory_access(directory_path) == 0) {  
        printf("Access control successfully implemented.\n");  
    } else {  
        printf("Failed to implement access control.\n");  
    }  

    return 0;  
}

