// Function to write firewall rules to /etc/ufw.rules
void writeFirewallRules(const std::vector<std::string>& ipList) {
    std::ofstream rulesFile("/etc/ufw.rules");
    if (!rulesFile.is_open()) {
        std::cerr << "Error: Could not open /etc/ufw.rules for writing." << std::endl;
        return;
    }

    for (const auto& ip : ipList) {
        rulesFile << "ufw allow from " << ip << " to any port 80" << std::endl;
        rulesFile << "ufw allow from " << ip << " to any port 443" << std::endl;
    }

    rulesFile.close();
    std::cout << "Firewall rules written successfully to /etc/ufw.rules" << std::endl;
}

