// Function to check if an IP address is in a given CIDR range
bool isIPInRange(const string& ip, const string& cidr) {
    // Parse CIDR notation
    size_t pos = cidr.find('/');
    if (pos == string::npos) return false;
    string ipRange = cidr.substr(0, pos);
    int prefixLen = stoi(cidr.substr(pos + 1));

    // Convert IP address to 32-bit integer
    unsigned int ipInt = 0;
    stringstream ss(ip);
    string octet;
    while (getline(ss, octet, '.')) {
        ipInt = ipInt * 256 + stoi(octet);
    }

    // Convert CIDR range to 32-bit integer
    unsigned int rangeStart = 0;
    stringstream ssRange(ipRange);
    string octetRange;
    while (getline(ssRange, octetRange, '.')) {
        rangeStart = rangeStart * 256 + stoi(octetRange);
    }

    // Calculate subnet mask
    unsigned int subnetMask = 0;
    for (int i = 0; i < prefixLen; i++) {
        subnetMask |= (1 << (31 - i));
    }

    // Check if IP address is in the range
    unsigned int rangeEnd = rangeStart | (~subnetMask);
    return (ipInt >= rangeStart && ipInt <= rangeEnd);
}

