// Function to search for a configuration file by name in common directories  
vector<string> searchConfigFile(const string& filename) {  
    vector<string> results;  
    // Define common directories where configuration files might be located  
    vector<string> directories = {"/etc", "/usr/local/etc", "/opt/local/etc", "/home", "/var/lib"};  

    for (const auto& dir : directories) {  
        try {  
            if (filesystem::exists(dir)) {  
                string path = dir + "/" + filename;  
                if (filesystem::exists(path)) {  
                    results.push_back(path);  
                }  
            }  
        } catch (const filesystem::filesystem_error& e) {  
            cerr << "Error accessing directory: " << e.what() << endl;  
        }  
    }  

    return results;  
}  

// Function to update a configuration file without overwriting the original  
bool updateConfigFile(const string& filepath, const string& newContent) {  
    ifstream file(filepath);  
    string originalContent;  
    string tempFilePath = filepath + ".tmp";  

    if (!file.is_open()) {  
        cerr << "Error opening file for reading: " << filepath << endl;  
        return false;  
    }  

    // Read the original content  
    while (getline(file, originalContent)) {  
        // Process each line to update if needed  
        // Example: Replace a specific value in the configuration  
        if (originalContent.find("debug_mode") != string::npos) {  
            originalContent.replace(originalContent.find("debug_mode"), 13, "debug_mode=true");  
        }  
    }  

    // Write the updated content to a temporary file  
    ofstream tempFile(tempFilePath);  
    if (!tempFile.is_open()) {  
        cerr << "Error creating temporary file: " << tempFilePath << endl;  
        return false;  
    }  

    tempFile << newContent;  
    tempFile.close();  

    // Replace the original file with the updated one  
