// Function to check if a file exists
bool fileExists(const string& filename) {
    struct stat buffer;
    return (stat(filename.c_str(), &buffer) == 0);
}

// Function to write a firewall rule to /etc/ufw/rules.v4
void writeFirewallRule(const string& ip) {
    ofstream file("/etc/ufw/rules.v4", ios::app);
    if (!file.is_open()) {
        cerr << "Error opening /etc/ufw/rules.v4 for writing." << endl;
        return;
    }

    // Write the firewall rule
    file << "allow from " << ip << " to any port 80,443 (10 minutes)" << endl;
    file << "deny from " << ip << " to any port 80,443 (24 hours)" << endl;
    file.close();
}

// Function to log errors to /var/log/ufw.log
void logError(const string& message) {
    ofstream file("/var/log/ufw.log", ios::app);
    if (!file.is_open()) {
        cerr << "Error opening /var/log/ufw.log for writing." << endl;
        return;
    }

    // Write the error message
    file << "[" << ctime(&time(0)) << "] ERROR: " << message << endl;
    file.close();
}

