const std::string BLOCK_LIST_FILE = "/var/lib/blocklist.txt";

// Mutex for thread-safe operations
std::mutex block_list_mutex;

// Block list structure
struct BlockEntry {
    std::string ip_address;
    std::string reason;
    std::string timestamp;
};

// Function to read block list from file
std::vector<BlockEntry> readBlockList() {
    std::vector<BlockEntry> block_list;
    std::ifstream file(BLOCK_LIST_FILE);
    std::string line;

    if (!file.is_open()) {
        std::cerr << "Error opening block list file: " << BLOCK_LIST_FILE << std::endl;
        return block_list;
    }

    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string ip, reason;
        std::getline(iss, ip, ',');
        std::getline(iss, reason);

        if (!ip.empty() && !reason.empty()) {
            BlockEntry entry;
            entry.ip_address = ip;
            entry.reason = reason;
            entry.timestamp = std::to_string(std::time(nullptr));
            block_list.push_back(entry);
        }
    }

    file.close();
    return block_list;
}

// Function to write block list to file
void writeBlockList(const std::vector<BlockEntry>& block_list) {
    std::ofstream file(BLOCK_LIST_FILE);
    if (!file.is_open()) {
        std::cerr << "Error opening block list file for writing: " << BLOCK_LIST_FILE << std::endl;
        return;
    }

    for (const auto& entry : block_list) {
        file << entry.ip_address << "," << entry.reason << std::endl;
    }

    file.close();
}

