// Function to check if an IP address is in the trusted list
bool isTrustedIP(const std::string& ip, const std::set<std::string>& trustedIPs) {
    return trustedIPs.find(ip) != trustedIPs.end();
}

// Function to log blocked IP addresses with reasons
void logBlockedIP(const std::string& ip, const std::string& reason) {
    std::ofstream logFile("blocked_ips.log", std::ios::app);
    if (logFile.is_open()) {
        logFile << std::left << std::setw(15) << ip << " | " << reason << std::endl;
        logFile.close();
    }
}

