};

// Define a rule structure
struct Rule {
    std::string condition;
    std::string action;
    std::string description;
};

// Global variables
std::vector<Rule> rules;
std::mutex rules_mutex;
std::mutex alert_mutex;
std::string alert_log_file = "security_alerts.log";

// Function to parse and update rules from a file
void updateRuleset(const std::string& filename) {
    std::ifstream file(filename);
    std::string line;
    std::regex rule_pattern(R"(^(\S+)\s+(\S+)\s+(.+)$)");

    if (!file.is_open()) {
        std::cerr << "Error opening rules file: " << filename << std::endl;
        return;
    }

    rules.clear();
    while (std::getline(file, line)) {
        std::smatch matches;
        if (std::regex_match(line, matches, rule_pattern)) {
            Rule rule;
            rule.condition = matches[1].str();
            rule.action = matches[2].str();
            rule.description = matches[3].str();
            std::lock_guard<std::mutex> lock(rules_mutex);
            rules.push_back(rule);
        }
    }
    file.close();
}

