    std::string authorizedUsersArray[100]; // Assuming maximum 100 authorized users
    std::string authorizedPasswordsArray[100]; // Assuming maximum 100 authorized passwords

    int userCount = 0;
    int passwordCount = 0;

    // Parse the authorized users string
    std::string userToken;
    std::istringstream iss1(authorizedUsersStr);
    while (std::getline(iss1, userToken, ',')) {
        authorizedUsersArray[userCount] = userToken;
        userCount++;
    }

    // Parse the authorized passwords string
    std::string passwordToken;
    std::istringstream iss2(authorizedPasswordsStr);
    while (std::getline(iss2, passwordToken, ',')) {
        authorizedPasswordsArray[passwordCount] = passwordToken;
        passwordCount++;
    }

    // Check if the username and password match any authorized user-password pair
    for (int i = 0; i < userCount; i++) {
        if (username == authorizedUsersArray[i]) {
            if (password == authorizedPasswordsArray[i]) {
                return true; // User is authorized
            }
        }
    }

