// Define a structure to represent an IP address and its status
struct IPAddress {
    string ip;
    bool isBlocked;
    time_t lastBlockedTime;
    bool isWhitelisted;
    string reason;
};

// Define a map to store the IP address data
map<string, IPAddress> ipMap;

// Define a mutex for thread-safe access to the map
mutex ipMutex;

// Define a function to check if an IP address is blocked
bool isIPBlocked(const string& ip) {
    lock_guard<mutex> lock(ipMutex);
    auto it = ipMap.find(ip);
    if (it != ipMap.end()) {
        return it->second.isBlocked;
    }
    return false;
}

// Define a function to block an IP address
void blockIP(const string& ip, const string& reason) {
    lock_guard<mutex> lock(ipMutex);
    auto it = ipMap.find(ip);
    if (it != ipMap.end()) {
        it->second.isBlocked = true;
        it->second.lastBlockedTime = time(nullptr);
        it->second.reason = reason;
    } else {
        IPAddress newIP;
        newIP.ip = ip;
        newIP.isBlocked = true;
        newIP.lastBlockedTime = time(nullptr);
        newIP.reason = reason;
        ipMap[ip] = newIP;
    }
}

// Define a function to unblock an IP address after a certain period of time
void unblockIP(const string& ip) {
    lock_guard<mutex> lock(ipMutex);
    auto it = ipMap.find(ip);
    if (it != ipMap.end()) {
        if (time(nullptr) - it->second.lastBlockedTime > 3600) { // Unblock after 1 hour
            it->second.isBlocked = false;
        }
    }
}

// Define a function to check if an IP address is whitelisted
bool isIPWhitelisted(const string& ip) {
    lock_guard<mutex> lock(ipMutex);
    auto it = ipMap.find(ip);
    if (it != ipMap.end()) {
        return it->second.isWhitelisted;
    }
    return false;
}

