struct FirewallRule {
    std::string ip_address;
    std::string action; // "block" or "allow"
    std::string timestamp;
    std::string duration; // e.g., "24h"
};

// Global variables for logging and blocking
std::vector<FirewallRule> firewall_rules;
std::mutex rules_mutex;
std::string log_file_path = "ddos_block_log.txt";

// Function to parse IP addresses from input string
std::vector<std::string> parseIPs(const std::string& input) {
    std::vector<std::string> ips;
    std::stringstream ss(input);
    std::string ip;
    while (std::getline(ss, ip, ',')) {
        ip.erase(std::remove(ip.begin(), ip.end(), ' '), ip.end());
        if (!ip.empty()) {
            ips.push_back(ip);
        }
    }
    return ips;
}

// Function to generate timestamp
std::string generateTimestamp() {
    auto now = std::chrono::system_clock::now();
    auto time_t = std::chrono::system_clock::to_time_t(now);
    std::stringstream ss;
    ss << std::put_time(std::localtime(&time_t), "%Y-%m-%d %H:%M:%S");
    return ss.str();
}

// Function to block an IP address
void blockIP(const std::string& ip) {
    std::lock_guard<std::mutex> lock(rules_mutex);
    FirewallRule rule;
    rule.ip_address = ip;
    rule.action = "block";
    rule.timestamp = generateTimestamp();
    rule.duration = "24h";
    firewall_rules.push_back(rule);
    std::cout << "Blocked IP address: " << ip << std::endl;
}

