// Function to update block list from external source
vector<string> update_block_list(const vector<string>& new_ips, const string& timestamp) {
    vector<string> updated_list;
    {
        lock_guard<mutex> lock(block_list_mutex);
        // Add new IPs to the list
        for (const string& ip : new_ips) {
            if (ip.empty()) continue;
            // Validate IP address format
            regex ip_pattern(R"(^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$)");
            if (regex_match(ip, ip_pattern)) {
                updated_list.push_back(ip);
            }
        }
        // Remove duplicates
        vector<string> unique_ips;
        for (const string& ip : updated_list) {
            if (find(unique_ips.begin(), unique_ips.end(), ip) == unique_ips.end()) {
                unique_ips.push_back(ip);
            }
        }
        blocked_ips = unique_ips;
    }
    cout << "Block list updated at " << timestamp << endl;
    return blocked_ips;
}

