// Define a packet structure  
struct Packet {  
    string source_ip;  
    string destination_ip;  
    int port;  
    string protocol;  
    string payload;  
};  

// Define a rule structure  
struct Rule {  
    string source_ip;  
    string destination_ip;  
    int port;  
    string protocol;  
    string action; // "block" or "allow"  
};  

// Global variables  
vector<Rule> rules;  
vector<Packet> blocked_packets;  
mutex packet_mutex;  
mutex rule_mutex;  

// Function to update the ruleset  
void update_ruleset(const string& filename) {  
    ifstream file(filename);  
    if (!file.is_open()) {  
        cerr << "Error opening rules file: " << filename << endl;  
        return;  
    }  

    rules.clear();  
    string line;  
    while (getline(file, line)) {  
        if (line.empty() || line[0] == '#') continue;  
        Rule rule;  
        size_t pos = line.find(" ");  
        if (pos == string::npos) continue;  
        rule.source_ip = line.substr(0, pos);  
        line = line.substr(pos + 1);  
        pos = line.find(" ");  
        if (pos == string::npos) continue;  
        rule.destination_ip = line.substr(0, pos);  
        line = line.substr(pos + 1);  
        pos = line.find(" ");  
        if (pos == string::npos) continue;  
        rule.port = stoi(line.substr(0, pos));  
        line = line.substr(pos + 1);  
        pos = line.find(" ");  
        if (pos == string::npos) continue;  
        rule.protocol = line.substr(0, pos);  
        line = line.substr(pos + 1);  
        rule.action = line;  
        rules.push_back(rule);  
    }  
    file.close();  
}  

