// Global variables
const int BLOCK_DURATION_HOURS = 24;
const string LOG_FILE_PATH = "blocked_traffic.log";
const int MAX_BLOCKED_IPS = 1000;

// Mutex for thread-safe operations
mutex log_mutex;

// Map to store blocked IP addresses and their block timestamps
map<string, time_t> blocked_ips;

// Function to block an IP address
void block_ip(const string& ip) {
    // Check if IP is already blocked
    if (blocked_ips.find(ip) != blocked_ips.end()) {
        cout << "IP address " << ip << " is already blocked." << endl;
        return;
    }

    // Block the IP address
    blocked_ips[ip] = time(nullptr);

    // Log the block event
    {
        lock_guard<mutex> lock(log_mutex);
        ofstream log_file(LOG_FILE_PATH, ios::app);
        if (log_file.is_open()) {
            log_file << "[" << ctime(&time(nullptr)) << "]";
            log_file << "Blocked IP address: " << ip << endl;
            log_file.close();
        }
    }

    cout << "IP address " << ip << " has been blocked for 24 hours." << endl;
}

// Function to unblock an IP address
void unblock_ip(const string& ip) {
    // Check if IP is blocked
    if (blocked_ips.find(ip) == blocked_ips.end()) {
        cout << "IP address " << ip << " is not blocked." << endl;
        return;
    }

    // Unblock the IP address
    blocked_ips.erase(ip);

    cout << "IP address " << ip << " has been unblocked." << endl;
}

// Function to check if an IP address is blocked
bool is_ip_blocked(const string& ip) {
    return blocked_ips.find(ip) != blocked_ips.end();
}

