// Function to check if a specific file exists in the directory
bool checkFileInDirectory(const std::string& directoryPath, const std::string& fileName) {
    struct stat buffer;
    std::string filePath = directoryPath + "/" + fileName;

    if (stat(filePath.c_str(), &buffer) == 0) {
        return true; // File exists
    } else {
        return false; // File does not exist
    }
}

// Signal handler function to terminate the process
void signalHandler(int signal) {
    std::cout << "Unauthorized access detected! Terminating process...\n";
    exit(1);
}

int main() {
    // Define the directory path and filename to check for
    std::string directoryPath = "/path/to/your/directory"; // Replace with actual path
    std::string fileName = "unauthorized_access.txt"; // Replace with actual filename

    // Set up signal handler for termination
    signal(SIGTERM, signalHandler);
    signal(SIGINT, signalHandler);

    // Check if the file exists in the directory
    if (checkFileInDirectory(directoryPath, fileName)) {
        std::cout << "Unauthorized access detected! Terminating process...\n";
        exit(1);
    }

    // If no unauthorized access is detected, continue with normal execution
    std::cout << "Access granted. Continuing execution...\n";

    // Example: Simulate some work
    for (int i = 0; i < 10; ++i) {
        std::cout << "Working on task " << i << std::endl;
        sleep(1);
    }

    return 0;
}

