std::vector<std::string> parseIPs(const std::string& input) {
    std::vector<std::string> ips;
    std::istringstream iss(input);
    std::string ip;

    while (std::getline(iss, ip, ',')) {
        std::istringstream ipStream(ip);
        std::string segment;
        std::vector<std::string> segments;

        while (std::getline(ipStream, segment, '.')) {
            segments.push_back(segment);
        }

        // Validate IP format
        if (segments.size() == 4) {
            for (const auto& seg : segments) {
                if (seg.empty() || seg.size() > 3 || !std::all_of(seg.begin(), seg.end(), ::isdigit)) {
                    continue;
                }
            }
            ips.push_back(ip);
        }
    }

    return ips;
}

