// Function to check if a user has access to the repository
bool hasAccess(const string& username, const string& password) {
    // Read authorized users and passwords from configuration file
    ifstream file("config.txt");
    string line;
    vector<pair<string, string>> authorizedUsers;

    if (!file.is_open()) {
        cerr << "Error opening configuration file!" << endl;
        return false;
    }

    while (getline(file, line)) {
        // Skip empty lines and comments
        if (line.empty() || line[0] == '#') {
            continue;
        }

        // Parse username and password from the line
        stringstream ss(line);
        string user, pass;
        getline(ss, user, ':');
        getline(ss, pass);

        // Store authorized user-password pair
        authorizedUsers.push_back(make_pair(user, pass));
    }

    // Check if provided credentials match any authorized entry
    for (const auto& entry : authorizedUsers) {
        if (entry.first == username && entry.second == password) {
            return true;
        }
    }

    return false;
}

