// Function to query VirusTotal API
std::string queryVirusTotal(const std::string& fileHash) {
    std::string url = "https://www.virustotal.com/api/v3/files/" + fileHash;
    CURL* curl = curl_easy_init();
    if (!curl) return "Error initializing curl";

    std::string response;
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* ptr, size_t size, size_t nmemb, void* userdata) {
        std::string* response = static_cast<std::string*>(userdata);
        response->append(static_cast<char*>(ptr), size * nmemb);
        return size * nmemb;
    });
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

    CURLcode res = curl_easy_perform(curl);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) return "Error querying VirusTotal API";

    // Parse JSON response to check for malware signatures
    Json::Value root;
    Json::Reader reader;
    if (!reader.parse(response, root)) {
        return "Error parsing JSON response";
    }

    // Check if the file is flagged as malicious
    if (root["data"]["attributes"]["last_analysis_stats"]["malicious"] > 0) {
        return "Malicious file detected";
    }

    return "No malware signatures found";
}

