// Function to check if the current user is root
bool isRoot() {
    return (getuid() == 0);
}

// Function to log access attempts
void logAccessAttempt(const string& username, const string& directory) {
    ofstream logFile("/var/log/directory_access.log", ios::app);
    if (logFile.is_open()) {
        logFile << "[" << ctime(&time(0)) << "]";
        logFile << "User: " << username << " attempted to access directory: " << directory << endl;
        logFile.close();
    }
}

// Function to block access to a specific directory
void blockDirectoryAccess(const string& directory) {
    // Check if the directory exists
    struct stat buffer;
    if (stat(directory.c_str(), &buffer) != 0) {
        cerr << "Error: Directory does not exist." << endl;
        return;
    }

    // Check if the current user is root
    if (!isRoot()) {
        logAccessAttempt(getpwuid(getuid())->pw_name, directory);
        cerr << "Access denied. Only root users can block directory access." << endl;
        return;
    }

    // Set directory permissions to restrict access
    mode_t permissions = S_IRUSR | S_IXUSR; // Read and execute for owner only
    if (chmod(directory.c_str(), permissions) != 0) {
        cerr << "Error: Failed to set directory permissions." << endl;
        return;
    }

    cout << "Directory access blocked successfully." << endl;
}

// Main function
int main(int argc, char* argv[]) {
    if (argc != 2) {
        cerr << "Usage: " << argv[0] << " <directory_path>" << endl;
        return 1;
    }

    string directoryPath = argv[1];
    blockDirectoryAccess(directoryPath);

    return 0;
}

