    std::mutex frequencyMutex;
    std::mutex patternMutex;
    std::chrono::steady_clock::time_point lastUpdate;

public:
    NetworkTrafficMonitor() {
        lastUpdate = std::chrono::steady_clock::now();
    }

    void addSuspiciousPattern(const std::string& pattern) {
        std::lock_guard<std::mutex> lock(patternMutex);
        suspiciousPatterns.push_back(pattern);
    }

    void updatePacketFrequency(const std::string& packet) {
        std::lock_guard<std::mutex> lock(frequencyMutex);
        packetFrequencyMap[packet]++;
    }

    bool isSuspicious(const std::string& packet) {
        std::lock_guard<std::mutex> lock(patternMutex);
        for (const auto& pattern : suspiciousPatterns) {
            if (packet.find(pattern) != std::string::npos) {
                return true;
            }
        }
        return false;
    }

    void learnFromExperience(const std::string& packet, bool isMalicious) {
        std::lock_guard<std::mutex> lock(frequencyMutex);
        packetFrequencyMap[packet] += isMalicious ? 1 : 0;
    }

    void analyzeTraffic() {
        std::this_thread::sleep_for(std::chrono::seconds(1));
        std::lock_guard<std::mutex> lock(frequencyMutex);
        for (const auto& [packet, frequency] : packetFrequencyMap) {
            if (frequency > 10) { // Threshold for suspicious activity
                std::cout << "Blocking suspicious packet: " << packet << std::endl;
            }
        }
    }
};

