    }
    std::cout << "Threshold value updated to: " << threshold << std::endl;
}

// Function to block suspicious IP addresses based on threshold
std::vector<std::string> blockSuspiciousIPs(const std::vector<std::string>& ipAddresses, double threshold) {
    std::vector<std::string> blockedIPs;
    for (const auto& ip : ipAddresses) {
        // Simulate suspicious IP detection logic
        // In a real-world scenario, this would involve checking against known malicious IP databases
        // For demonstration purposes, we'll use a simple heuristic
        if (ip.find("192.168") != std::string::npos || ip.find("10.") != std::string::npos) {
            blockedIPs.push_back(ip);
        }
    }
    return blockedIPs;
}

// Function to log blocked IP addresses to a file
void logBlockedIPs(const std::vector<std::string>& blockedIPs, const std::string& logFile) {
    std::ofstream file(logFile, std::ios::app);
    if (file.is_open()) {
        for (const auto& ip : blockedIPs) {
            file << ip << std::endl;
        }
        file.close();
    } else {
        std::cerr << "Error opening log file for writing." << std::endl;
    }
}

