// Define a simple rule structure
struct Rule {
    std::string protocol;
    std::string source_ip;
    std::string destination_ip;
    int source_port;
    int destination_port;
    std::string action; // "block", "allow", "log"
    std::string description;
};

// Global variables
std::vector<Rule> rules;
std::mutex rule_mutex;
std::map<std::string, std::vector<std::string>> traffic_patterns;
std::map<std::string, std::vector<std::string>> blocked_ips;

// Function to parse traffic patterns from a file
void parse_traffic_patterns(const std::string& filename) {
    std::ifstream file(filename);
    std::string line;
    while (std::getline(file, line)) {
        std::regex pattern_regex(R"((\w+):(\d+))");
        std::smatch matches;
        if (std::regex_search(line, matches, pattern_regex)) {
            std::string protocol = matches[1];
            int port = std::stoi(matches[2]);
            traffic_patterns[protocol].push_back(std::to_string(port));
        }
    }
}

// Function to block a packet based on rules
void block_packet(const std::string& src_ip, const std::string& dst_ip, int src_port, int dst_port, const std::string& protocol) {
    std::lock_guard<std::mutex> lock(rule_mutex);
    for (const auto& rule : rules) {
        if (rule.protocol == protocol && rule.source_ip == src_ip && rule.destination_ip == dst_ip && 
            rule.source_port == src_port && rule.destination_port == dst_port) {
            std::cout << "Blocking packet: " << src_ip << ":" << src_port << " -> " << dst_ip << ":" << dst_port << std::endl;
            return;
        }
    }
    std::cout << "No rule found to block packet: " << src_ip << ":" << src_port << " -> " << dst_ip << ":" << dst_port << std::endl;
}

