            std::cerr << "Error updating block list: " << e.what() << std::endl;
        }
    }

    // Function to check if a given IP address is in the block list
    bool isBlocked(const std::string& ip) {
        try {
            // Check if the IP address is in the blocked list
            for (const auto& blocked_ip : blocked_ips) {
                if (ip == blocked_ip) {
                    return true;
                }
            }
            return false;
        } catch (const std::exception& e) {
            std::cerr << "Error checking IP address: " << e.what() << std::endl;
            return false;
        }
    }

    // Function to handle exceptions and display an error message to the user
    void handleError(const std::string& message) {
        std::cerr << "Error: " << message << std::endl;
    }
};

