    std::thread rotationThread;
    bool isRotating;
    std::chrono::time_point<std::chrono::system_clock> lastRotationTime;

public:
    KeyRotationManager() : isRotating(false), lastRotationTime(std::chrono::system_clock::now()) {
        // Initialize with a default key
        currentKey = generateRandomKey();
    }

    void startRotation() {
        if (rotationThread.joinable()) {
            rotationThread.join();
        }
        isRotating = true;
        rotationThread = std::thread(&KeyRotationManager::rotateKeys, this);
    }

    void stopRotation() {
        isRotating = false;
        if (rotationThread.joinable()) {
            rotationThread.join();
        }
    }

    std::string getCurrentKey() {
        std::lock_guard<std::mutex> lock(keyMutex);
        return currentKey;
    }

    std::string getRotatedKey() {
        std::lock_guard<std::mutex> lock(keyMutex);
        return rotatedKey;
    }

    void rotateKeys() {
        while (isRotating) {
            std::this_thread::sleep_for(std::chrono::hours(24));
            std::lock_guard<std::mutex> lock(keyMutex);
            rotatedKey = generateRandomKey();
            std::swap(currentKey, rotatedKey);
            std::cout << "Key rotation completed successfully at " << std::chrono::system_clock::now().time_since_epoch().count() << std::endl;
        }
    }

    std::string generateRandomKey() {
        unsigned char buffer[32];
        RAND_bytes(buffer, 32);
        std::string key(buffer, buffer + 32);
        return key;
    }
};

