// Function to check if a directory is accessible
bool isDirectoryAccessible(const std::string& directory) {
    struct stat buffer;
    if (stat(directory.c_str(), &buffer) == 0) {
        return S_ISDIR(buffer.st_mode);
    }
    return false;
}

