// Function to read and parse the block list from a file  
void load_block_list(const std::string& filename) {  
    std::ifstream file(filename);  
    std::string line;  
    blocked_ips.clear();  

    if (!file.is_open()) {  
        std::cerr << "Error: Could not open block list file: " << filename << std::endl;  
        return;  
    }  

    while (std::getline(file, line)) {  
        // Trim whitespace and newline characters  
        line.erase(0, line.find_first_not_of(' '));  
        line.erase(line.find_last_not_of(' ') + 1);  

        // Validate IP address format (basic check)  
        if (line.length() >= 7 && line.find('.') != std::string::npos) {  
            blocked_ips.push_back(line);  
        }  
    }  

    file.close();  
    std::cout << "Block list loaded successfully from: " << filename << std::endl;  
}  

