import java.util.stream.Collectors;

// Traffic Flow Analyzer Class
public class TrafficFlowAnalyzer {
    private final Map<String, Double> baselineMetrics = new ConcurrentHashMap<>();
    private final List<NetworkFlow> observedFlows = new ArrayList<>();
    private final ExecutorService analyzerPool = Executors.newFixedThreadPool(4);

    // Statistical baseline calculation using moving window approach
    public void establishBaseline(int windowSize) {
        baselineMetrics.clear();
        for (NetworkFlow flow : observedFlows) {
            double avgBytesPerSecond = calculateAverageBytes(flow);
            double packetRate = flow.getPacketCount() / flow.getDuration();
            baselineMetrics.put(flow.getFlowId(), avgBytesPerSecond);
        }
    }

    // Machine learning feature extraction for anomaly scoring
    public double calculateAnomalyScore(NetworkFlow flow) {
        double currentBytesPerSecond = calculateAverageBytes(flow);
        double packetRate = flow.getPacketCount() / flow.getDuration();

        // Statistical deviation calculation
        double deviation = Math.abs(currentBytesPerSecond - baselineMetrics.get(flow.getFlowId()));

        // Machine learning feature vector construction
        List<Double> features = Arrays.asList(
            deviation,
            packetRate,
            flow.getProtocol().getAnomalyScore(),
            flow.getDestinationPort().getRiskLevel()
        );

        // Ensemble scoring using weighted contributions
        double anomalyScore = features.stream()
            .mapToDouble(f -> f * getFeatureWeight(f))
            .sum();

        return anomalyScore;
    }

    // Feature weight determination based on traffic characteristics
    private double getFeatureWeight(double featureValue) {
        if (featureValue < 0.1) return 0.3;
        else if (featureValue < 0.5) return 0.5;
        else return 0.8;
    }
}
