import com.sun.management.OperatingSystemMXBean;
import java.lang.management.ManagementFactory;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class CpuUsageMonitor implements Runnable {
    private static final int POLL_INTERVAL_MS = 5000; // 5-second polling
    private static final int ALERT_THRESHOLD = 85; // 85% CPU threshold

    private OperatingSystemMXBean osBean;
    private ScheduledExecutorService scheduler;
    private AtomicInteger alertCount = new AtomicInteger(0);

    public CpuUsageMonitor() {
        this.osBean = ManagementFactory.getOperatingSystemMXBean();
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    @Override
    public void run() {
        while (true) {
            try {
                double cpuUsage = osBean.getSystemCpuLoad();
                if (cpuUsage > ALERT_THRESHOLD) {
                    triggerAlert(cpuUsage);
                }
                Thread.sleep(POLL_INTERVAL_MS);
            } catch (Exception e) {
                System.err.println("Error monitoring CPU usage: " + e.getMessage());
            }
        }
    }

    private void triggerAlert(double usage) {
        System.out.printf("ALERT: CPU usage exceeds threshold (%.2f%%)\n", usage);
        alertCount.incrementAndGet();
    }

    public void startMonitoring() {
        scheduler.scheduleAtFixedRate(this, 0, POLL_INTERVAL_MS, TimeUnit.MILLISECONDS);
    }

    public void stopMonitoring() {
        scheduler.shutdown();
    }
